\label{Adam}
\caption{Adam}
\textbf{Input:} Stochastic oracle \( \mathcal{O} \), initial learning rate \( \eta_{t} >0 \), initial parameters \( w_1 \in \mathbb{R}^d \), initial exponential moving averages \( m_0 = 0 \), \( v_0 = v \cdot \mathbf{1}^\top \) with \( v > 0 \), hyperparameters \( \beta_1, \beta_{2,1} \in [0,1) \), smoothing term \( \mu > 0 \), number of iterations \( T \)\\
\textbf{Output:} Final parameter \( w_T \)
\begin{algorithmic}[1]
\For{$t = 1$ \textbf{to} $T$}
    \State Generate conditioner parameter \( \beta_{2,t} \);
    \State Sample a random data point \( z_t \) and compute the stochastic gradient \( g_t = \mathcal{O}_f(w_t, z_t) \);
    \State Update the second moment estimate: \( v_t = \beta_{2,t} v_{t-1} + (1 - \beta_{2,t}) g_t^{\circ 2} \);
    \State Update the first moment estimate: \( m_t = \beta_{1} m_{t-1} + (1 - \beta_{1}) g_t \);
    \State Compute the adaptive learning rate: \( \eta_{v_{t}} = \eta_{t} \cdot \frac{1}{\sqrt{v_{t}} + \mu} \);
    \State Update the parameters: \( w_{t+1} = w_t - \eta_{v_{t}} \circ m_t \);
\EndFor
\end{algorithmic}

\begin{assumpt}\label{ass_3}
(\textbf{ABC Inequality}) We assume that the stochastic gradient \( g_t \) is an unbiased estimate of the true gradient, i.e., $\mathbb{E}[g_{t} \mid \mathscr{F}_{t-1}] = \nabla f(w_{t}),$ and there exist constants \( A, B, C \geq 0 \) such that for all iterations \( t \), we have:
\(
\mathbb{E}[\|g_{t} \|^2 \mid \mathscr{F}_{t-1}] \leq A (f(w_t) - f^*) + B \|\nabla f(w_t)\|^{2} + C.
\)
\end{assumpt}

\label{thm:complexity}
Consider the Adam algorithm as specified in Algorithm~\ref{Adam}, and assume that Assumptions~\ref{ass_1}--\ref{ass_3} are satisfied. Then, for any initial point, any \( T \geq 1 \), and any \( s \in (0,1) \), the following bound holds with probability at least \( 1 - s \):
\begin{align*}
 \frac{1}{T}\sum_{t=1}^{T}\|\nabla f(w_{t})\|^{2}\le  \begin{cases} 
\mathcal{O}\Big(\frac{1}{s^2}\frac{1}{T^{\frac{1}{2}-\delta}}\Big), & \text{if }\delta\in(0,1/2)  \\
\mathcal{O}\Big(\frac{1}{s^2}\frac{\ln T}{\sqrt{T}}\Big), & \text{if } \gamma>1,\ \ \delta = 0\\
\mathcal{O}\Big(\frac{1}{s^2}\frac{\ln^{2} T}{\sqrt{T}}\Big), & \text{if } \gamma=1,\ \ \delta = 0.\end{cases} \tag*{\qedhere}
\end{align*}
The constant implied by the \( \mathcal{O} \) notation depends on the initial point, the constants in Assumptions~\ref{ass_1}--\ref{ass_3} (excluding \( 1/\mu \)), and the parameters \( \delta \) and \( \alpha_0 \).

\label{thm:almost_sure}
Under Assumptions \ref{ass_1}--\ref{ass_3}, consider the Adam with hyperparameters specified in Subsection \ref{setting} with \( \gamma > 1 \) and \( \delta > 0 \). Then, the gradients of the Adam converge to zero almost surely, i.e.,
\(
\lim_{t \to \infty} \|\nabla f(w_t)\| = 0 \quad \text{a.s.}
\)

\begin{property}\label{property_1}
Each element \(\eta_{v_{t},i}\) of the sequence \(\{\eta_{v_{t}}\}_{t\ge 1} = \{[\eta_{v_{t},1}, \eta_{v_{t},2}, \ldots, \eta_{v_{t},d}]^{\top}\}_{t\ge 1}\) satisfies the inequality \(t^{\gamma}v_{t,i}\ge \alpha_{1}S_{t,i},\) where we define \(\alpha_{1}:=\min\{1-\alpha_{0},\alpha_{0}\},\) \(S_{t,i}:=v+\sum_{k=1}^{t}g_{k,i}^{2}\) for all \( t\ge 1 \), and \(S_{0,i}:=v.\)
\end{property}

