\label{sufficient:decrease}
Consider the sequences \(\{w_{t}\}_{t\ge 1}\), \(\{v_{t}\}_{t\ge 1}\), and \(\{u_{t}\}_{t\ge 1}\) generated by Algorithm \ref{Adam} and Eq. \ref{u_{t}}. Under Assumptions \ref{ass_1}--\ref{ass_3}, the following sufficient decrease inequality holds:
\begin{align}\label{adam_16}
\Pi_{\Delta,t}\hat{f}(u_{t+1})-\Pi_{\Delta,t-1}\hat{f}(u_{t})&\le-\frac{1}{2}\Pi_{\Delta,t}\sum_{i=1}^{d}\zeta_{i}(t)\notag+C_{2}\|{\eta_{v_{t-1}}}\circ m_{t-1}\|^{2}+\sum_{i=1}^{d}\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|\\&+(L_{f}+1)\sum_{i=1}^{d}\eta_{v_{t},i}^{2}g_{t,i}^{2}+\Pi_{\Delta,t}M_{t}.
\end{align}
Here,
\begin{align}\label{Delta}
&\hat{f}(u_{t}):=f(u_{t})-f^*+C\sum_{i=1}^{d}\eta_{v_{t-1},i},\notag\ \ \zeta_{i}(t):=\eta_{v_{t},i}(\nabla_{i}f(w_{t}))^{2},\notag\\
&\Pi_{\Delta,t}:=\prod_{k=1}^{t}\left(1+\left(\frac{D_1}{1-\sqrt{\beta_{1}}}+1\right)\overline{\Delta}_{\sqrt{\beta_{1}},k}\right)^{-1}\ (t\ge 1),\ \Pi_{\Delta,0}:=1,\notag\ \   \\&\overline{\Delta}_{\sqrt{\beta_{1}},k} := \sum_{i=1}^{d}\mathbb{E}\left[\sum_{t=k}^{+\infty} (\sqrt{\beta_{1}})^{t-k} \Delta_{t,i}\bigg|\mathscr{F}_{k-1}\right],\notag\\
&M_{t}:=M_{t,1}+M_{t,2}+M_{t,3}.
\end{align}
Constants \( D_{1} \) is defined in Lemma \ref{property_3.510}; \( M_{t,1} \) is defined in Eq. \ref{adam_0}; \( M_{t,2} \) and \( M_{t,3} \) are defined in Eq. \ref{adam_2}.

We obtain the following expression (informal):
\begin{align}\label{informal}
    f(u_{t+1})-f(u_{t})\le & -\underbrace{\sum_{i=1}^{d}\mathbb{E}\left[\eta_{v_{t},i}\nabla f(w_{t})g_{t,i}|\mathscr{F}_{t-1}\right]}_{\emph{Term}_{t,1}}+\underbrace{\mathcal{O}\left(\sum_{i=1}^{d}\eta_{v_{t},i}^{2}g_{t,i}^{2}\right)}_{\emph{Term}_{t,2}}\notag\\&+\underbrace{\sum_{i=1}^{d}\mathbb{E}\left[\eta_{v_{t},i}\nabla f(w_{t})g_{t,i}|\mathscr{F}_{t-1}\right]-\sum_{i=1}^{d}\eta_{v_{t},i}\nabla f(w_{t})g_{t,i}}_{\emph{Term}_{t,3}}+R_{t}.
\end{align}
It can be observed that the above equation is simply a second-order Taylor expansion of $f(u_{t+1}) - f(u_{t})$ (since an L-smooth function is almost everywhere twice differentiable). $\emph{Term}_{t,1}$ represents the first-order term, which in general serves as the descent term. $\emph{Term}_{t,2}$ is the quadratic error, and $\emph{Term}_{t,3}$ is a martingale difference sequence. The remaining term $R_{t}$ is negligible and can be ignored. In the informal explanation provided in the sketch, these were collectively referred to as remainder terms. For the exact formulation, refer to the detailed proof in Appendix \ref{proof of sufficient}.

Multiplying both sides of the inequality by $\Pi_{\Delta,t}$, we obtain the following reformulated inequality:
\begin{align}\label{informal2}
    \Pi_{\Delta,t}f(u_{t+1})-\Pi_{\Delta,t-1}f(u_{t})&\le -\frac{1}{2}\Pi_{\Delta,t}\cdot\emph{Descent-Term}_{t}+\Pi_{\Delta,t}\cdot\emph{M-Term}_{t}\notag\\
    &+\Pi_{\Delta,t}\cdot \emph{Term}_{t,2}+\Pi_{\Delta,t+1}\cdot\emph{R-Term}_{t}.
\end{align}
This reformulation introduces $\Pi_{\Delta,t}$ as a scaling factor, which, along with the original Lyapunov function, captures the impact of $\emph{Term}_{t,4}$. The resulting inequality closely parallels the approximate descent inequality for SGD, with additional terms accounting for Adam's adaptive nature.

Due to Algorithm \ref{Adam}, we observe that
\[v_{t+1}=\beta_{2,t+1}v_{t}+(1-\beta_{2,t+1})g_{t+1}^{\circ 2}=\Big(1-\frac{1}{(t+1)^{\gamma}}\Big)v_{t}+\frac{1}{(t+1)^{\gamma}}g_{t+1}^{\circ 2},\ (\forall\ t\ge 1).\]
which means
\begin{align}\label{jh_100}
(t+1)^{\gamma}v_{t+1,i}=\big((t+1)^{\gamma}-1\big)v_{t,i}+ g_{t+1,i}^{2}\ge t^{\gamma}v_{t,i}.
\end{align}
This implies that \(tv_{t,i}\) is monotonically non-decreasing. Subsequently, we have
\begin{align*}
\eta_{v_{t},i}=\frac{\eta_{t}}{\sqrt{v_{t,i}}+\mu}=\frac{\sqrt{t^{\gamma}}\eta_{t}}{\sqrt{t^{\gamma}v_{t,i}}+\sqrt{t^{\gamma}}\mu}=\frac{\frac{1}{t^{\delta-\frac{\gamma-1}{2}}}}{\sqrt{tv_{t,i}}+\sqrt{t^{\gamma}}\mu}.
\end{align*} Because the numerator is monotonically decreasing and greater than 0, while the denominator is monotonically non-increasing and greater than $0$, we deduce the monotonic non-increasing property of \(\eta_{v_{t}}.\)

According to Algorithm \ref{Adam}, we have the following iterative equations
\begin{align*}
m_{t,i}=\beta_{1}m_{t-1,i}+(1-\beta_{1})g_{t,i}.
\end{align*}
We take the square of the 2-norm on both sides, which yields
\begin{align*}
m_{t,i}^{2}&=(\beta_{1}m_{t-1,i}+(1-\beta_{1})g_{t,i})^{2}\notag\\&=\beta_{1}^{2}m_{t-1,i}^{2}+2\beta_{1}(1-\beta_{1})m_{t-1,i}g_{t,i}+(1-\beta_{1})^{2}g_{t,i}^{2}\notag\\&\mathop{\le}^{(a)}\beta_{1}m_{t-1,i}^{2}+(1-\beta_{1})g_{t,i}^{2}.
\end{align*}
In step (a), we used the \emph{AM-GM} inequality, i.e.,
\[2\beta_{1}(1-\beta_{1})m_{t-1,i}g_{t,i}\le \beta_{1}(1-\beta_{1})m_{t-1,i}^{2}+\beta_{1}(1-\beta_{1})g_{t,i}^{2},\] that is,
\begin{align*}
m_{t,i}^{2}-m_{t-1,i}^{2}\le -(1-\beta_{1})m_{t-1,i}^{2}+(1-\beta_{1})g_{t,i}^{2},
\end{align*}
which completes the proof.

Due to
\begin{align*}
|f(w_t)-f(u_t)|&=\bigg|\nabla f(u_{t})^{\top}(w_t-u_t)+\frac{L_{f}}{2}\|w_t-u_t\|^{2}\bigg|\le \|\nabla f(u_{t})\|\|w_t-u_t\|+\frac{L_{f}}{2}\|w_t-u_t\|^{2}\\&\le \frac{1}{2}\|\nabla f(u_{t})\|^{2}+\frac{L_{f}+1}{2}\|w_{t}-u_{t}\|^{2}\\&={L} f(u_{t})+\frac{(L_{f}+1)\beta_{1}^{2}}{2(1-\beta_1)^{2}}\|\eta_{v_{t-1}}\circ m_{t-1}\|^{2},
\end{align*}
we have
\begin{align*}
    f(w_{t})\le f(u_{t})+|f(w_t)-f(u_t)|\le (L_{f}+1)f(u_{t})+\frac{(L_{f}+1)\beta_{1}^{2}}{2(1-\beta_1)^{2}}\|\eta_{v_{t-1}}\circ m_{t-1}\|^{2}. \tag*{\qedhere}
\end{align*}

\label{exchange}
If $0<\mu<1$ and $0<\sigma<1$ ($\sigma< \mu$) are two constants, then for any positive sequence $\{\psi_{n}\}$, there is
\begin{equation}\nonumber\begin{aligned}
\sum_{i=1}^{n}\mu^{n-i}\psi_{i}<\sum_{k=1}^{n}\mu^{n-k}\sum_{i=1}^{k}\sigma^{k-i}\psi_{i}\le 1/{\big(1-\omega_{0}\big)}\sum_{i=1}^{n}\mu^{n-i}\psi_{i}, \end{aligned}\end{equation} where $\omega_{0}:=\sigma/\mu.$

\label{loss_bound} 
Suppose that $f(x)$ is differentiable and lower bounded, i.e. $ f^{\ast} = \inf_{x\in \ \mathbb{R}^{d}}f(x) >-\infty$, and $\nabla f(x)$ is Lipschitz continuous with parameter $\mathcal{L} > 0$, then $\forall \ x\in \ \mathbb{R}^{d}$, we have
\begin{align*}
\big\|\nabla f(x)\big\|^{2}\le {2\mathcal{L}}\big(f(x)-f^{*}\big).
\end{align*}

\label{lem_important_-1}
Let \(\{(X_n, \mathscr{F}_n)\}_{n \geq 1}\) be a non-negative adapted process such that \(\sum_{n=1}^{+\infty} X_n = M < +\infty\) almost surely, where \(M\) is a finite constant. Define the partial sum of conditional expectations as \(\Lambda_T := \sum_{n=1}^{T} \mathbb{E}[X_n \mid \mathscr{F}_{n-1}]\). Then the following properties hold.
\begin{itemize}
    \item[(i)] The sequence \(\{\Lambda_T\}_{T \geq 1}\) converges almost surely, i.e., \(\Lambda_T \xrightarrow{a.s.} \Lambda\), where \(\Lambda := \sum_{n=1}^{+\infty} \mathbb{E}[X_n \mid \mathscr{F}_{n-1}]\).

    \item[(ii)] For any \(p \geq 1\), the sequence \(\{\Lambda_T\}_{T \geq 1}\) converges in \(L_p\), i.e., \(\lim_{T \to \infty} \mathbb{E}\left[|\Lambda_T - \Lambda|^p\right] = 0\). Meanwhile, the \(p\)-th moment of the limit \(\Lambda\) is bounded by a constant \(C_{\Lambda}(p) > 0,\) where \(C_{\Lambda}(p) = o(p^{\sqrt{p}}).\)




\end{itemize}

The proof of this lemma is through identities. We assume $\mu>\sigma$ (the case  $\mu<\sigma$ is the similar), and let $\omega_{0}=\log_{\mu}\sigma>1$. Then we derive
\begin{equation}\nonumber\begin{aligned}
&\sum_{k=1}^{n}\mu^{n-k}\sum_{i=1}^{k}\sigma^{k-i}\psi_{i}=\sum_{k=1}^{n}\sum_{i=1}^{k}\mu^{n-k}\sigma^{k-i}\psi_{i}=\sum_{i=1}^{n}\sum_{k=i}^{n}\mu^{n-k}\sigma^{k-i}\psi_{i}=\sum_{i=1}^{n}\left(\sum_{k=i}^{n}\left(\frac{\sigma}{\mu}\right)^{k-i}\right)
\mu^{n-i}\psi_{i},
\end{aligned}\end{equation}
 where $\omega_{0}=\sigma/\mu.$ Then combining $1<\sum_{k=i}^{n}\left(\frac{\sigma}{\mu}\right)^{k-i}<\frac{1}{1-\omega_{0}}$ we get the result.

