\label{lem_sum'}
Consider the Adam algorithm in Algorithm \ref{Adam} and suppose that Assumption \ref{ass_1} - \ref{ass_3} hold. Then for any initial point, and $T \geq 1$, the following results hold
\begin{align*}
&\mathbb{E}[\Pi_{\Delta,T}(f(w_{T})-f^*)]=\mathcal{O}\left(\sum_{t=1}^{T}\mathbb{E}\|\eta_{v_{t}}\circ g_{t}\|^{2}\right)+\mathcal{O}(1),  
\\&\sum_{t=1}^{T}\mathbb{E}\left[\Pi_{\Delta,t}\sum_{i=1}^{d}\zeta_{i}(t)\right]=\mathcal{O}\left(\sum_{t=1}^{T}\mathbb{E}\|\eta_{v_{t}}\circ g_{t}\|^{2}\right)+\mathcal{O}(1),
\\&\sum_{t=1}^{T}\sum_{i=1}^{d}\mathbb{E}\left[\Pi_{\Delta,t}\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|\right]=\mathcal{O}\left(\sum_{t=1}^{T}\mathbb{E}\|\eta_{v_{t}}\circ g_{t}\|^{2}\right)+\mathcal{O}(1).
\end{align*}
The specific form of the constants hidden behind the \(\mathcal{O}()\) notation can be found in Equation (\ref{adam_w_2'}) and Equation (\ref{adam_w_2''}). All constants depend on the initial point and the constants in our required assumptions (excluding $1/\mu$).

\label{vital_1}
Consider the Adam algorithm defined in Algorithm \ref{Adam} and suppose that Assumption \ref{ass_1}$ - $\ref{ass_3} hold. Then for any initial point and $\forall\ \phi>0$, we have for any $T \geq 1,$ the following inequality holds
\begin{align}\label{adam_-11.5}
\frac{\Pi_{\Delta,T}\sqrt{S_{T}}}{(T+1)^{\phi}}\le  {\sqrt{dv}}+\sum_{t=1}^{T}\Pi_{\Delta,t}\Lambda_{\phi,t},
\end{align}
where 
\[\Lambda_{\phi,t}:=\frac{\|g_{t}\|^{2}}{(t+1)^{\phi}\sqrt{S_{t-1}}},\] and $S_{T}$ is defined in Remark \ref{S_t}.

\label{vital_0}
Consider the Adam algorithm defined in Algorithm \ref{Adam} and suppose that Assumptions \ref{ass_1} - \ref{ass_3} hold. Then for any initial point and for all $T \geq 1$, there exists a random variable $\zeta$ such that the following results hold
