\begin{align*}
    \sum_{t=1}^{T}\mathbb{E}\bigg[\Pi_{\Delta,t}\sum_{i=1}^{d}\zeta_{i}(t)\bigg]\le\begin{cases} 
C_{4,\delta}, & \text{if } \delta \in (0,1], \\
C_{5}+C_{6}\mathbb{E}\left[\ln(S_{T})\right], & \text{if } \delta = 0,\end{cases}
\end{align*}
where $C_{5}$ and $C_{6}$ are constants that depend on the initial point and the constants in our required assumptions (excluding $1/\mu$), and $C_{4,\delta}$ is a constant that depends on the initial point, $\delta$, and the constants in our required assumptions (excluding $1/\mu$).

