\label{lem_sum_1}
Under Assumption \ref{ass_1} - \ref{ass_3}, consider the Adam algorithm (Algorithm \ref{Adam}) with hyperparameters in Subsection \ref{setting} with $\gamma>1,\  \delta>0.$ Then for any initial point, the following results hold
\begin{align*}
    \sum_{t=1}^{+\infty}\eta_{t}\|\nabla f(w_{t})\|^{2}<+\infty\ \ \text{a.s.,}\ \ \sum_{t=1}^{+\infty}\eta_{t}\|\nabla f(u_{t})\|^{2}<+\infty\ \ \text{a.s.},\ \ \text{and}\ \ 
\sum_{t=1}^{+\infty}\|\eta_{v_{t}}\circ m_{t}\|^{2} <+\infty\ \ \text{a.s.} 
\end{align*}

By the $L$-smoothness in Assumption \ref{ass_2}, we have:
\begin{align*}
f(u_{t+1})-f(u_{t})\le \nabla f(u_{t})^{\top}(u_{t+1}-u_{t})+\frac{L_{f}}{2}\|u_{t+1}-u_{t}\|^{2}.     
\end{align*}
Then, by substituting the iterative formula for \( u_{t} \) from Equation (\ref{u_{t}}) into the above inequality, we obtain
\begin{align}\label{adam_-1}
f(u_{t+1})-f(u_{t})\le & -\sum_{i=1}^{d}\eta_{v_{t},i}\nabla_{i} f(u_{t})g_{t,i}+\frac{\beta_{1}}{1-\beta_{1}}\sum_{i=1}^{d}\Delta_{t,i}\nabla_{i} f(u_{t})m_{t-1,i}+{L_{f}}\sum_{i=1}^{d}\eta_{v_{t},i}^{2}g_{t,i}^{2}\notag\\&+L_{f}\Big(\frac{\beta_{1}}{1-\beta_{1}}\Big)^{2}\sum_{i=1}^{d}\Delta_{t,i}^{2}m_{t-1,i}^{2}\notag\\
\mathop{=}^{(a)} &\underbrace{-\sum_{i=1}^{d}\eta_{v_{t},i}\nabla_{i}f(w_{t})g_{t,i}}_{\Theta_{t,1}}+\underbrace{\sum_{i=1}^{d}(\eta_{v_{t},i}(\nabla_{i}f(w_{t})-\nabla_{i}f(u_{t}))g_{t,i})}_{\Theta_{t,2}}\notag\\&+\frac{\beta_{1}}{1-\beta_{1}}\underbrace{\sum_{i=1}^{d}\Delta_{t,i}\nabla_{i} f(u_{t})m_{t-1,i}}_{\Theta_{t,3}}+{L_{f}}\sum_{i=1}^{d}\eta_{v_{t},i}^{2}g_{t,i}^{2}\notag\\&+L_{f}\Big(\frac{\beta_{1}}{1-\beta_{1}}\Big)^{2}\underbrace{\sum_{i=1}^{d}\Delta_{t,i}^{2}m_{t-1,i}^{2}}_{\Theta_{t,4}}.
\end{align}
Step $(a)$ employs the identity $\nabla_{i} f(u_{t})=\nabla_{i} f(w_{t}) + \nabla_{i} f(u_{t}) - \nabla_{i} f(w_{t}).$ Next, we handle $\Theta_{t,1},$ $\Theta_{t,2},$ $\Theta_{t,3}$ and $\Theta_{t,4}$ separately. First, for $\Theta_{t,1},$ we use the following identity.
\begin{align}\label{adam_0}
\Theta_{t,1}&=-\sum_{i=1}^{d}\eta_{v_{t},i}\nabla_{i}f(w_{t})g_{t,i}=-\sum_{i=1}^{d}\eta_{v_{t-1},i}\nabla_{i}f(w_{t})g_{t,i}+\sum_{i=1}^{d}\Delta_{t,i}\nabla_{i}f(w_{t})g_{t,i}\notag\\&=-\sum_{i=1}^{d}\underbrace{\eta_{v_{t-1},i}(\nabla_{i}f(w_{t}))^{2}}_{\zeta_{i}(t)}+\underbrace{\sum_{i=1}^{d}\Delta_{t,i}\nabla_{i}f(w_{t})g_{t,i}}_{\Theta_{t,1,1}}+\underbrace{\sum_{i=1}^{d}\eta_{v_{t-1},i}\nabla_{i}f(w_{t})(\nabla_{i} f(w_{t})-g_{t,i})}_{M_{t,1}},
\end{align}
where $\Delta_{t,i}$ in the above equality represents the $i$-th component of the vector $\Delta_{t}$, which is defined in Equation (\ref{u_{t}}). In this way, we decompose $\Theta_{1}$ into a descent term $-\sum_{i=1}^{d}\zeta_{i}(t)$, an error term $\Theta_{t,1,1}$, and a martingale difference term $M_{t,1}$. We will further scale and control the error term $\Theta_{t,1,1}$. Specifically, we have
\begin{align}\label{adam_2}
\Theta_{t,1,1}=&\ \sum_{i=1}^{d}\mathbb{E}\big(\Delta_{t,i}\nabla_{i}f(w_{t})g_{t,i}\mid\mathscr{F}_{t-1}\big)\notag\\
&+\underbrace{\sum_{i=1}^{d}\big(\Delta_{t,i}\nabla_{i}f(w_{t})g_{t,i}-\mathbb{E}\big[\Delta_{t,i}\nabla_{i}f(w_{t})g_{t,i}\mid\mathscr{F}_{t-1}\big]}_{M_{t,2}}\big)\notag\\
\mathop{<}^{(a)}&\ \sum_{i=1}^{d}\sqrt{\eta_{v_{t-1},i}}\nabla_{i}f(w_{t})\mathbb{E}\big[\sqrt{\Delta_{t,i}}{g_{t,i}}\mid\mathscr{F}_{t-1}\big]+M_{t,2}\notag\\
\mathop{\le}^{(b)}&\  \frac{1}{2}\sum_{i=1}^{d}\eta_{v_{t-1},i}(\nabla_{i} f(w_{t}))^{2}+\frac{1}{2}\sum_{i=1}^{d}\mathbb{E}^{2}\big[\sqrt{\Delta_{t,i}}{g_{t,i}}\mid\mathscr{F}_{t-1}\big]+M_{t,2}\notag\\
\mathop{\le}^{(c)}&\  \frac{1}{2}\sum_{i=1}^{d}\zeta_{i}(t)+\frac{1}{2}\sum_{i=1}^{d}\mathbb{E}[g^{2}_{t,i}\mid\mathscr{F}_{t-1}]\cdot\mathbb{E}[\Delta_{t,i}\mid\mathscr{F}_{t-1}]+M_{t,2}\notag\\
\le&\  \frac{1}{2}\sum_{i=1}^{d}\zeta_{i}(t)+\frac{1}{2}\sum_{i=1}^{d}\mathbb{E}[g^{2}_{t,i}\mid\mathscr{F}_{t-1}]\cdot\mathbb{E}[\Delta_{t,i}\mid\mathscr{F}_{t-1}]+M_{t,2}\notag\\
\le&\ \frac{1}{2}\sum_{i=1}^{d}\zeta_{i}(t)+\frac{1}{2}\Bigg(\sum_{i=1}^{d}\mathbb{E}[g^{2}_{t,i}\mid\mathscr{F}_{t-1}]\Bigg)\cdot\Bigg(\sum_{i=1}^{d}\mathbb{E}[\Delta_{t,i}\mid \mathscr{F}_{t-1}]\Bigg)+M_{t,2}\notag\\
\mathop{\le}^{(d)}&\ \frac{1}{2}\sum_{i=1}^{d}\zeta_{i}(t)+\frac{1}{2}\Bigg((A+2L_{f}B)f(w_{t})+C\Bigg)\cdot\Bigg(\sum_{i=1}^{d}\mathbb{E}[\Delta_{t,i}\mid \mathscr{F}_{t-1}]\Bigg)+M_{t,2}\notag\\
=&\ \frac{1}{2}\sum_{i=1}^{d}\zeta_{i}(t)+\frac{1}{2}(A+2L_{f}B)f(w_{t})\cdot\Bigg(\sum_{i=1}^{d}\mathbb{E}[\Delta_{t,i}\mid \mathscr{F}_{t-1}]\Bigg)\notag\\
&+C\Bigg(\sum_{i=1}^{d}\mathbb{E}[\Delta_{t,i}\mid \mathscr{F}_{t-1}]\Bigg)+M_{t,2}\notag\\
=&\ \frac{1}{2}\sum_{i=1}^{d}\zeta_{i}(t)+\frac{1}{2}(A+2L_{f}B)f(w_{t})\cdot\Bigg(\underbrace{\sum_{i=1}^{d}\mathbb{E}[\Delta_{t,i}\mid \mathscr{F}_{t-1}]}_{\overline{\Delta}_{t}}\Bigg)+C\sum_{i=1}^{d}\Delta_{t,i}\notag\\
&+\underbrace{C\Bigg(\sum_{i=1}^{d}\Big(\mathbb{E}[\Delta_{t,i}\mid\mathscr{F}_{t-1}]-\Delta_{t,i}\Big)\Bigg)}_{M_{t,3}}+M_{t,2}.
\end{align}



In the above derivation, in step $(a)$, we utilized the property of conditional expectation, which states that for random variables \(X \in \mathscr{F}_{n-1}\) and \(Y \in \mathscr{F}_{n}\), we have \(\mathbb{E}[XY|\mathscr{F}_{n-1}] = X\mathbb{E}[Y|\mathscr{F}_{n-1}]\). Additionally, note that \(\Delta_{t,i} = \sqrt{\Delta_{t,i}}\sqrt{\Delta_{t,i}} < \sqrt{\eta_{v_{t-1}}}\sqrt{\Delta_{t,i}}\) (due to Property \ref{property_0}, we know \(\Delta_{t,i} \ge 0\), so taking the square root is well-defined). In step $(b)$, we employed the \emph{AM-GM} inequality, which states \(ab \le \frac{a^{2} + b^{2}}{2}\). In step $(c)$, we used the \emph{Cauchy-Schwarz} inequality for conditional expectations, namely \(\mathbb{E}[XY|\mathscr{F}_{n-1}] \le \sqrt{\mathbb{E}[X^{2}|\mathscr{F}_{n-1}] \mathbb{E}[Y^{2}|\mathscr{F}_{n-1}]}.\) For step $(d)$, we used Property \ref{property_-1}. Specifically, we have
\begin{align*}
\sum_{i=1}^{d}\mathbb{E}[g_{t,i}^{2}|\mathscr{F}_{t-1}]=\mathbb{E}[\|g_{t}\|^{2}|\mathscr{F}_{t-1}]\le (A+2L_{f}B)f(w_{t})+C.
\end{align*}












Substituting the estimate of $\Theta_{t,1,1}$ into Equation (\ref{adam_2}), we obtain
\begin{align*}
\Theta_{t,1}&=-\frac{1}{2}\sum_{i=1}^{d}\zeta_{i}(t)+\frac{A+2L_{f}B}{2}\overline{\Delta}_{t}\cdot f(w_t)+C\sum_{i=1}^{d}\Delta_{t,i}+\underbrace{M_{t,1}+M_{t,2}+M_{t,3}}_{M_{t}}.
\end{align*}
Then, we use Property \ref{property_2} to replace $f(w_t)$ with $f(u_t)$ to obtain
\begin{align}\label{adam_3}
\Theta_{t,1}&=-\frac{1}{2}\sum_{i=1}^{d}\zeta_{i}(t)+\frac{(A+2L_{f}B)(L_{f}+1)}{2}\overline{\Delta}_{t}\cdot f(u_t)+C\sum_{i=1}^{d}\Delta_{t,i}\notag\\&+\frac{(L_{f}+1)\beta_{1}^{2}}{2(1-\beta_1)^{2}}\|\eta_{v_{t-1}}\circ m_{t-1}\|^{2}+M_{t}.
\end{align}
Next, we handle the term $\Theta_{t,2}$ through the following derivation.
\begin{align}\label{adam_5}
\Theta_{t,2}=&\ \frac{1}{2}\sum_{i=1}^{d}(\eta_{v_{t},i}(\nabla_{i}f(w_{t})-\nabla_{i}f(u_{t}))g_{t,i})\notag\\
\le&\ \sum_{i=1}^{d}\eta^{2}_{v_{t},i}g^{2}_{t,i}+\frac{1}{2}\sum_{i=1}^{d}(\nabla_{i}f(w_{t})-\nabla_{i}f(u_{t}))^{2}\notag\\
=&\ \sum_{i=1}^{d}\eta^{2}_{v_{t},i}g^{2}_{t,i}+\frac{1}{2}\|\nabla f(w_{t})-\nabla f(u_t)\|^{2}\notag\\ 
\le&\ \sum_{i=1}^{d}\eta^{2}_{v_{t},i}g^{2}_{t,i}+\frac{L_{f}^{2}}{2}\|w_{t}-u_{t}\|^{2}\notag\\
=&\ \sum_{i=1}^{d}\eta^{2}_{v_{t},i}g^{2}_{t,i}+\frac{\beta_{1}^{2}L_{f}^{2}}{2(1-\beta_{1})^{2}}\|\eta_{v_{t-1}}\circ m_{t-1}\|^{2}.
\end{align}
Next, we handle the term $\Theta_{t,3}$. We have
{\begin{align}\label{adam_11}
\Theta_{t,3}&=\sum_{i=1}^{d}\Delta_{t,i}\nabla_{i} f(u_{t})m_{t-1,i}\le\sum_{i=1}^{d}\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|.
\end{align}}










For $\Theta_{t,4},$ because $\Delta_{t,i}\le \eta_{v_{t-1},i}$, we obtain that
\begin{align}\label{adam_15}
\Theta_{t,4}=\sum_{i=1}^{d}\Delta_{t,i}^{2}m_{t-1,i}^{2}<\sum_{i=1}^{d}\eta^{2}_{v_{t-1},i}m_{t-1,i}^{2}=\|\eta_{v_{t-1}}\circ m_{t-1}\|^{2}.
\end{align}
Finally, substituting the estimates of $\Theta_{t,1}$ from Equation (\ref{adam_3}), $\Theta_{t,2}$ from Equation (\ref{adam_5}), $\Theta_{t,3}$ from Equation (\ref{adam_11}), and $\Theta_{t,4}$ from Equation (\ref{adam_15}) back into Equation (\ref{adam_-1}), we obtain




\begin{align*}
&\bigg(\underbrace{{f(u_{t+1})-f^*+C\sum_{i=1}^{d}\eta_{v_{t},i}}}_{\hat{f}(u_{t+1})}\bigg)-\bigg(\underbrace{{f(u_{t})-f^*+C\sum_{i=1}^{d}\eta_{v_{t-1},i}}}_{\hat{f}(u_{t})}\bigg)\le-\frac{1}{2}\sum_{i=1}^{d}\zeta_{i}(t)+C_{1}\overline{\Delta}_{t}\cdot f(u_{t})\notag\\&+C_{2}\|{\eta_{v_{t-1}}}\circ m_{t-1}\|^{2}+\sum_{i=1}^{d}\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|+(L_{f}+1)\sum_{i=1}^{d}\eta_{v_{t},i}^{2}g_{t,i}^{2}+M_{t},
\end{align*}
where
\begin{align}\label{adam_20}
&C_{1}:=\frac{(A+2L_{f}B)(L_{f}+1)}{2},\ \ C_{2}:=\frac{\beta_{1}^{2}L_{f}^{2}}{2(1-\beta_{1})^{2}}+L_{f}\Big(\frac{\beta_{1}}{1-\beta_{1}}\Big)^{2}.
\end{align}
To the second term on the right side of the above inequality, we apply the inequality $\$[f(u_{t}) < f(u_{t})-f^* + C\sum_{i=1}^{d}\eta_{v_{t-1},i}=\hat{f}(u_{t})$ and then move the expanded term to the left side of the inequality. This obtains
\begin{align*}
\hat{f}(u_{t+1})-(1+C_{1}\overline{\Delta}_{t})\hat{f}(u_{t})\le& -\frac{1}{2}\sum_{i=1}^{d}\zeta_{i}(t)+C_{1}\overline{\Delta}_{t}\cdot f(u_{t})\notag\\&\ +C_{2}\|{\eta_{v_{t-1}}}\circ m_{t-1}\|^{2}+\sum_{i=1}^{d}\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|\\&\ +(L_{f}+1)\sum_{i=1}^{d}\eta_{v_{t},i}^{2}g_{t,i}^{2}+M_{t}.
\end{align*}


























Next, we define
\begin{align*}
    \overline{\Delta}_{\sqrt{\beta_{1}},k} := \sum_{i=1}^{d}\mathbb{E}\left[\sum_{t=k}^{+\infty} (\sqrt{\beta_{1}})^{t-k} \Delta_{t,i}\bigg|\mathscr{F}_{k-1}\right].
\end{align*}
Observe that
\[1 + C_{1} \overline{\Delta}_{t} \leq 1 + \left(\frac{D_1}{1 - \sqrt{\beta_{1}}} + 1\right) \overline{\Delta}_{\sqrt{\beta_{1}},t},\]
where \(D_{1}\) is defined in Lemma \ref{property_3.510}. Thus, we have
\begin{align*}
\hat{f}(u_{t+1})-\left(1 + \left(\frac{D_1}{1 - \sqrt{\beta_{1}}} + 1\right) \overline{\Delta}_{\sqrt{\beta_{1}},t}\right)\hat{f}(u_{t})\le& -\frac{1}{2}\sum_{i=1}^{d}\zeta_{i}(t)+C_{1}\overline{\Delta}_{t}\cdot f(u_{t})\notag\\&\ +C_{2}\|{\eta_{v_{t-1}}}\circ m_{t-1}\|^{2}+\sum_{i=1}^{d}\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|\\&\ +(L_{f}+1)\sum_{i=1}^{d}\eta_{v_{t},i}^{2}g_{t,i}^{2}+M_{t}.
\end{align*}
Next, we construct an auxiliary variable
\begin{align*}
\Pi_{\Delta,t}:=\prod_{k=1}^{t}\left(1+\left(\frac{D_1}{1-\sqrt{\beta_{1}}}+1\right)\overline{\Delta}_{\sqrt{\beta_{1}},k}\right)^{-1}\ (t\ge 1),\ \Pi_{\Delta,0}:=1.
\end{align*}
Multiplying both sides of the above inequality by $\Pi_{\Delta,t},$ we obtain
\begin{align*}
\Pi_{\Delta,t}\hat{f}(u_{t+1})-\Pi_{\Delta,t-1}\hat{f}(u_{t})\le &-\frac{1}{2}\Pi_{\Delta,t}\sum_{i=1}^{d}\zeta_{i}(t)\notag+C_{2}\|{\eta_{v_{t-1}}}\circ m_{t-1}\|^{2}+\sum_{i=1}^{d}\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|\\&\ +(L_{f}+1)\sum_{i=1}^{d}\eta_{v_{t},i}^{2}g_{t,i}^{2}+\Pi_{\Delta,t}M_{t}.
\end{align*}
With the inequality, we complete the proof.

For any $\phi \in \mathbb{R}$, we consider $\frac{\sqrt{S_{T}}}{(T+1)^{\phi}}$. We have
\begin{align*}
\frac{\sqrt{S_{T}}}{(T+1)^{\phi}}&=\frac{{S_{T}}}{(T+1)^{\phi}\sqrt{S_{T}}}=\frac{S_{0}+\sum_{t=1}^{T}\|g_{t}\|^{2}}{(T+1)^{\phi}\sqrt{S_{T}}} =\frac{S_{0}}{(T+1)^{\phi}\sqrt{S_{T}}} +\sum_{t=1}^{T}\frac{\|g_{t}\|^{2}}{(T+1)^{\phi}\sqrt{S_{T}}}\\&\le \frac{S_{0}}{(T+1)^{\phi}\sqrt{S_{T}}} +\sum_{t=1}^{T}\frac{\|g_{t}\|^{2}}{(T+1)^{\phi}\sqrt{S_{T}}}\le {\sqrt{S_{0}}}+\sum_{t=1}^{T}\frac{\|g_{t}\|^{2}}{(t+1)^{\phi}\sqrt{S_{t-1}}}\\&={\sqrt{dv}}+\sum_{t=1}^{T}\frac{\|g_{t}\|^{2}}{(t+1)^{\phi}\sqrt{S_{t-1}}}.
\end{align*}
By multiplying both sides of the above inequality by \(\Pi_{\Delta,T}\) and noting the monotonicity of \(\{\Pi_{\Delta,t}\}_{t \geq 1}\) as well as the fact that \(\Pi_{\Delta,T} \leq 1\) for all \(T \geq 1\), the lemma follows.

We take $\phi = 4$ in Lemma \ref{vital_1} and bound the expectation of the partial sum $\sum_{t=1}^{T}\Lambda_{4,t}$. We have
\begin{align}\label{dsacdqewed}
\mathbb{E}\Bigg[\sum_{t=1}^{T}\Pi_{\Delta,t}\Lambda_{4,t}\Bigg]&=\sum_{t=1}^{T}\mathbb{E}[\Pi_{\Delta,t}\Lambda_{4,t}]=\sum_{t=1}^{T}\mathbb{E}\Bigg[\frac{\Pi_{\Delta,t}\|g_{t}\|^{2}}{(t+1)^{4}\sqrt{S_{t-1}}}\Bigg]=\sum_{t=1}^{T}\mathbb{E}\Bigg[\frac{\Pi_{\Delta,t}\mathbb{E}[\|g_{t}\|^{2}|\mathscr{F}_{t-1}]}{(t+1)^{4}\sqrt{S_{t-1}}}\Bigg]\notag\\&\mathop{\le}^{\text{Property \ref{property_-1}}}\sum_{t=1}^{T}\mathbb{E}\Bigg[\frac{(A+2L_{f}B)\Pi_{\Delta,t}(f(w_{t})-f^*)+C}{(t+1)^{4}\sqrt{S_{t-1}}}\Bigg]\notag\\&\le C_{3}\sum_{t=1}^{T}\frac{1}{(t+1)^{4}}\mathbb{E}\left[\Pi_{\Delta,t}(f(w_{t})-f^*)\right]+C_{4}\sum_{t=1}^{T}\frac{1}{(t+1)^{4}},
\end{align}
where $$C_{3}:=\frac{A+2L_{f}B}{\sqrt{S_{0}}},\ C_{4}:=\frac{C}{\sqrt{S_{0}}}.$$
Based on the results in Lemma \ref{lem_sum'}, we can compute:
\begin{align*}
\mathbb{E}\left[\Pi_{\Delta,t}(f(w_{t})-f^*)\right]=\mathcal{O}\left(\sum_{k=1}^{t}\mathbb{E}\|\eta_{v_{k}}\circ g_{k}\|^{2}\right)+\mathcal{O}(1)=\mathcal{O}(t).
\end{align*}
Substitute the above result into Equation (\ref{dsacdqewed}), and combine $\forall\ p\ge 2$
\[\sum_{t=1}^{T}\frac{1}{(t+1)^{p}}\le\sum_{t=1}^{T}\frac{1}{(t+1)^{2}}\le \sum_{t=1}^{+\infty}\frac{1}{t^{2}}=\frac{\pi^{2}}{6}.\] We get
\[\mathbb{E}\Bigg[\sum_{t=1}^{T}\Pi_{\Delta,t}\Lambda_{4,t}\Bigg]=\mathcal{O}(1).\]
It can be observed that the right-hand side of the above inequality is independent of $T$. Thus, according to the \emph{Lebesgue's Monotone Convergence} theorem, we have 
\[\sum_{t=1}^{T}\Pi_{\Delta,t}\Lambda_{4,t} \to \sum_{t=1}^{+\infty}\Pi_{\Delta,t}\Lambda_{4,t} \quad \text{a.s.},\]
and
\[
\mathbb{E}\Bigg[\sum_{t=1}^{+\infty}\Pi_{\Delta,t}\Lambda_{4,t}\Bigg] = \lim_{T \to \infty} \mathbb{E}\Bigg[\sum_{t=1}^{T}\Pi_{\Delta,t}\Lambda_{4,t}\Bigg] = \lim_{T \to \infty} \sum_{t=1}^{T} \mathbb{E}[\Pi_{\Delta,t}\Lambda_{4,t}] =\mathcal{O}(1).
\]
By setting $$\zeta := \sqrt{dv} + \sum_{t=1}^{+\infty}\Pi_{\Delta,t}\Lambda_{4,t},$$ and combining Lemma \ref{vital_1}, we have
\begin{align}\label{power}
\sqrt{S_{T}}\le \Pi_{\Delta,T}^{-1} (T+1)^{4}\zeta<\Pi_{\Delta,\infty}^{-1} (T+1)^{4}\zeta.
\end{align}
Meanwhile,
\begin{align}\label{bound'}\mathbb{E}[\zeta]=\sqrt{dv}+\mathbb{E}\Bigg[\sum_{t=1}^{+\infty}\Lambda_{4,t}\Bigg]=\mathcal{O}(1).\end{align}
Then through Equation (\ref{power}), we have
\begin{align*}
\frac{1}{2}\ln\left(\frac{S_{T}}{v}\right)&\le 4\ln(T+1)+\ln\left(\Pi_{\Delta,\infty}^{-1}\zeta\right)\\&\le4\ln(T+1)+\ln\left(\max\left\{e,\Pi_{\Delta,\infty}^{-1}\zeta\right\}\right)\\&\le 4\ln(T+1)\left(1+\frac{\ln\left(\max\left\{e,\Pi_{\Delta,\infty}^{-1}\zeta\right\}\right)}{4\ln(T+1)}\right)\\&\mathop{\le}^{\ln(T+1)\ge 1/2}4\ln(T+1)\left(1+\frac{1}{2}{\ln\left(\max\left\{e,\Pi_{\Delta,\infty}^{-1}\zeta\right\}\right)}\right).
\end{align*}








The lemma follows

According to the second conclusion of Lemma \ref{lem_sum'}, we have
\begin{align*}
    \sum_{t=1}^{T}\mathbb{E}\left[\Pi_{\Delta,t}\sum_{i=1}^{d}\zeta_{i}(t)\right]=\mathcal{O}\left(\sum_{t=1}^{T}\mathbb{E}\|\eta_{v_{t}}\circ g_{t}\|^{2}\right)+\mathcal{O}(1).
