To prove the conclusion of this lemma, we only need to bound $\sum_{t=1}^{T}\mathbb{E}\|\eta_{v_{t}}\circ g_{t}\|^{2}.$ Specifically,
\begin{align}\label{Gamma_t}
\mathbb{E}\|\eta_{v_{t}}\circ g_{t}\|^{2}&=\mathbb{E}\left[\sum_{i=1}^{d}\eta_{v_{t},i}^{2}g_{t,i}^{2}\right]=\mathbb{E}\left[\sum_{i=1}^{d}\frac{\eta_{t}^{2}g_{t,i}^{2}}{(\sqrt{v_{t,i}}+\mu)^{2}}\right]\le \mathbb{E}\left[\sum_{i=1}^{d}\frac{1}{t^{2\delta}}\frac{g_{t,i}^{2}}{{tv_{t,i}}}\right]\notag\\&\mathop{\le}^{\text{Property \ref{property_1}}}\frac{(t+1)^{2\delta}}{t^{2\delta}}\mathbb{E}\left[\sum_{i=1}^{d}\frac{1}{\alpha_{1}(t+1)^{2\delta}}\frac{g_{t,i}^{2}}{{S_{t,i}}}\right]\\
&\mathop{\le}^{(a)}\frac{2^{2\delta}}{\alpha_{1}}{\zeta}^{\frac{\delta}{2}}\Pi^{-\frac{\delta}{2}}_{\Delta,\infty}\sum_{i=1}^{d}\frac{g_{t,i}^{2}}{{S_{t,i}}^{1+\frac{\delta}{4}}}.
\end{align}
In step $(a)$ of the above derivation, we apply Lemma \ref{vital_0} to $(t+1)^{2\delta}$. Specifically, according to Lemma \ref{vital_0}, we have
\begin{align*}
\sqrt{S_{t}}\le \Pi_{\Delta,\infty}^{-1}(t+1)^{4}\zeta.
\end{align*}




Next, with the estimate for $\mathbb{E}\|\eta_{v_{t}}\circ g_{t}\|^{2}$, we can estimate $\sum_{t=1}^{T}\mathbb{E}\|\eta_{v_{t}}\circ g_{t}\|^{2}$. To achieve this, note that
\begin{align}\label{Gamma}
\sum_{t=1}^{T} \mathbb{E}\|\eta_{v_{t}}\circ g_{t}\|^{2}&=\mathbb{E}\left[\frac{2^{2\delta}}{\alpha_{1}}{\zeta}^{\frac{\delta}{2}}\Pi^{-\frac{\delta}{2}}_{\Delta,\infty}\sum_{i=1}^{d}\sum_{t=1}^{T}\frac{g_{t,i}^{2}}{{S_{t,i}}^{1+\frac{\delta}{4}}}\right]\le \mathbb{E}\left[\frac{2^{2\delta}}{\alpha_{1}}{\zeta}^{\frac{\delta}{2}}\Pi^{-\frac{\delta}{2}}_{\Delta,\infty}\sum_{i=1}^{d}\int_{S_{0,i}}^{S_{T,i}}\frac{1}{{x}^{1+\frac{\delta}{4}}}\text{d}x\right]\notag\\&\le \begin{cases} 
\frac{2^{2\delta}}{\alpha_{1}}\mathbb{E}\left[{\zeta}^{\frac{\delta}{4}}\Pi^{-\frac{\delta}{2}}_{\Delta,\infty}\right], & \text{if } \delta \in (0,1] \\
\frac{2^{2\delta}}{\alpha_{1}}\mathbb{E}\left[\ln\big(\frac{S_{T}}{dv}\big)\right], & \text{if } \delta = 0
\end{cases}\notag\\&\mathop{\le}^{(b)}\begin{cases} 
\mathcal{O}(1), & \text{if } \delta \in (0,1] \\
\frac{d2^{2\delta}}{\alpha_{1}}\mathbb{E}\left[\ln\big(\frac{S_{T}}{dv}\big)\right], & \text{if } \delta = 0
\end{cases}.
\end{align}
In step $(b)$, we used the following inequality, i.e. the \emph{Hölder's} inequality, to obtain the $\mathcal{O}(1)$ result
\[\mathbb{E}\left[{\zeta}^{\frac{\delta}{4}}\Pi^{-\frac{\delta}{2}}_{\Delta,\infty}\right]\le \mathbb{E}^{\delta/4}\left[\zeta\right]\cdot\mathbb{E}^{\frac{4-\delta}{4}}\left[\Pi^{-\frac{2\delta}{4-\delta}}_{\Delta,\infty}\right]\mathop{\le}^{\text{Lemma \ref{bounded_moment} and \ref{vital_0}}} C_{\zeta}^{\delta/4}.C_{v,d,\frac{2\delta}{4-\delta}}^{\frac{4-\delta}{4}}=\mathcal{O}(1).\]
This completes the proof.

We only present the case where $\delta = 0$. The case where $\delta > 0$ can be treated using exactly the same approach. Recall the approximate descent inequality (Lemma \ref{sufficient:decrease})
\begin{align*}
\Pi_{\Delta,t}\hat{f}(u_{t+1})-\Pi_{\Delta,t-1}\hat{f}(u_{t})\le& -\frac{1}{2}\Pi_{\Delta,t}\sum_{i=1}^{d}\zeta_{i}(t)\notag+C_{2}\|{\eta_{v_{t-1}}}\circ m_{t-1}\|^{2}+\sum_{i=1}^{d}\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|\\&\ +(L_{f}+1)\sum_{i=1}^{d}\eta_{v_{t},i}^{2}g_{t,i}^{2}+\Pi_{\Delta,t}M_{t}.
\end{align*}
We divide both sides of the above inequality by $\ln^{2}(t+1)$. Noticing that $\ln^{2}(t+1) < \ln^{2}(t+2)$, we obtain
\begin{align}\label{adam_7980}
\frac{\Pi_{\Delta,t}\hat{f}(u_{t+1})}{\ln^{2}(t+2)}-\frac{\Pi_{\Delta,t-1}\hat{f}(u_{t})}{\ln^{2}(t+1)}&\le C_{2}\frac{\|{\eta_{v_{t-1}}}\circ m_{t-1}\|^{2}}{\ln^{2}(t+1)}+\sum_{i=1}^{d}\frac{\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|}{\ln^{2}(t+1)}\\&+(L_{f}+1)\sum_{i=1}^{d}\frac{\eta_{v_{t},i}^{2}g_{t,i}^{2}}{\ln^{2}(t+1)}+\Pi_{\Delta,t}\frac{M_{t}}{\ln^{2}(t+1)}.
\end{align}
Assign
$$\Omega_{t}:=C_{2}\frac{\|{\eta_{v_{t-1}}}\circ m_{t-1}\|^{2}}{\ln^{t+1}}+\sum_{i=1}^{d}\frac{\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|}{\ln^{2}(t+1)}+(L_{f}+1)\sum_{i=1}^{d}\frac{\eta_{v_{t},i}^{2}g_{t,i}^{2}}{\ln^{2}(t+1)}.$$
For the term \(\sum_{t=1}^{+\infty} \mathbb{E}[\Omega_{t}]\), we can estimate it as 
\begin{align*}
\sum_{t=1}^{+\infty}\mathbb{E}[\Omega_{t}]:=&\ C_{2}\sum_{t=1}^{+\infty}\frac{\mathbb{E}\|{\eta_{v_{t-1}}}\circ m_{t-1}\|^{2}}{\ln^{t+1}}+\sum_{t=1}^{+\infty}\sum_{i=1}^{d}\frac{\mathbb{E}[\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|]}{\ln^{2}(t+1)}\\&\ +(L_{f}+1)\sum_{i=1}^{d}\sum_{t=1}^{+\infty}\frac{\mathbb{E}[\eta_{v_{t},i}^{2}g_{t,i}^{2}]}{\ln^{2}(t+1)}\\ \mathop{\le}^{(a)} &\ \mathcal{O}(1)+\sum_{i=1}^{d}\mathcal{O}\left(\sum_{t=1}^{+\infty}\mathbb{E}\left[\frac{\mathbb{E}[\eta_{v_{t},i}^{2}g_{t,i}^{2}]}{\ln^{2}(t+1)}\right]\right)\\
\mathop{\le}^{(b)} &\ \mathcal{O}(1)+\sum_{i=1}^{d}\mathcal{O}\left(\sum_{t=1,S_{t,i}>2v}^{+\infty}\mathbb{E}\left[\zeta'^{2}\frac{\mathbb{E}[\eta_{v_{t},i}^{2}g_{t,i}^{2}]}{\ln^{2}\left(S_{t,i}/v\right)}\right]\right).
\end{align*}
In step $(a)$, we use Property \ref{property_3} and Lemma \ref{lem_sum'}. In step $(b)$, we use the last result from Lemma \ref{vital_0}, which states
$$\ln\Big(\frac{S_{t,i}}{v}\Big)\le\ln\Big(\frac{S_{t}}{v}\Big)\le \zeta'\ln (T+1).$$ Then, using the series-integral inequality, we bound $\sum_{t=1}^{+\infty} \mathbb{E}[\Omega_{t}]$ and obtain
\begin{align*}
    \sum_{t=1}^{+\infty}\mathbb{E}[\Omega_{t}]&\le \mathcal{O}(1)+\mathcal{O}\left(\sum_{i=1}^{d}\mathbb{E}\bigg[\sum_{t=1,S_{t,i}>2v}^{+\infty}\frac{({\zeta'}^{2})\frac{g_{t,i}^{2}}{v}}{\ln^{2}(\frac{S_{t,i}}{v})\frac{S_{t,i}}{v}}\bigg]\right)\\
    & <\mathcal{O}(1)+\mathcal{O}\left(\sum_{i=1}^{d}\mathbb{E}\Bigg[\int_{2}^{+\infty}\frac{{\zeta'}^{2}}{x\ln^{2}x}\text{d}x\Bigg]\right)\\&=\mathcal{O}(1)+\mathcal{O}(\mathbb{E}[\zeta'^{2}]).
\end{align*}
Next, we use the explicit expression for $\zeta'$ given in Lemma \ref{vital_0} to bound $\mathbb{E}[{\zeta'}^{2}]$. We have:
\begin{align*}
\mathbb{E}[{\zeta'}^{2}]&=\mathbb{E}\left[16\left(1+\frac{1}{2}{\ln\left(\max\left\{e,\Pi_{\Delta,\infty}^{-1}\zeta\right\}\right)}\right)\right]<+\infty.
\end{align*}
As a result, we have
\begin{align}\label{adam_7981}
     \sum_{t=1}^{+\infty}\mathbb{E}[\Omega_{t}]<+\infty.
\end{align}
According to the \emph{Lebesgue's Monotone Convergence} theorem, we know that the above result implies
\begin{align}\label{adam_7982}
\sum_{t=1}^{+\infty}\mathbb{E}[\Omega_{t}|\mathscr{F}_{t-1}]<+\infty\ \ \text{a.s.}
\end{align}
Next, we take the conditional expectation with respect to $\mathscr{F}_{t-1}$ on both sides of Equation (\ref{adam_7980}), which obtains
\begin{align}\label{adam_7980'}
\mathbb{E}\Bigg[\frac{\Pi_{\Delta,t+1}\hat{f}(u_{t+1})}{\ln^{2}(t+2)}\Bigg|\mathscr{F}_{t-1}\Bigg]\le \frac{\Pi_{\Delta,t}\hat{f}(u_{t})}{\ln^{2}(t+1)}+\mathbb{E}[{\Omega_{t}}|\mathscr{F}_{t-1}]+0.
\end{align}
Based on the result from Equation (\ref{adam_7982}) and the \emph{Supermartingale Convergence} theorem, we deduce that $\frac{\Pi_{\Delta,t}\hat{f}(u_{t})}{\ln^{2}(t+1)}$ converges almost surely. Then, according to Property \ref{property_2}, we bound ${f}(w_{t})-f^*$ using $\hat{f}(u_{t}).$ This concludes our first result. Next, we take the expectation on both sides of Equation (\ref{adam_7980}), which yields
\begin{align}\label{adam_7980''}
\mathbb{E}\Bigg[\frac{\Pi_{\Delta,t+1}\hat{f}(u_{t+1})}{\ln^{2}(t+2)}\Bigg]\le \mathbb{E}\Bigg[\frac{\Pi_{\Delta,t}\hat{f}(u_{t})}{\ln^{2}(t+1)}\Bigg]+\mathbb{E}[{\Omega_{t}}]+0.
\end{align}
Based on the convergence result of the expectation summation in Equation (\ref{adam_7981}) and a summation formula for a recursive sequence, we conclude our second result. Thus, the analysis for the case $\delta = 0$ has been completed. The case $\delta > 0$ could be analyzed using the same method, which concludes the lemma.

Since the case of $\delta > 0$ is relatively straightforward, we first analyze the scenario where $\delta > 0$. According to the second conclusion for $\delta > 0$ in Lemma \ref{lem_g}, we obtain
\begin{align*}
\mathbb{E}[{S^{3/4}_{T}}]=\mathbb{E}[\Pi_{\Delta,T}^{-3/4}\Pi^{3/4}_{\Delta,T}S^{3/4}_{T}]\mathop{\le}^{\text{\emph{Hölder's} inequality}} \mathbb{E}^{1/4}[\Pi_{\Delta,T}^{-3}]\mathbb{E}^{3/4}[\Pi_{\Delta,T}S_{T}].
\end{align*}
Then according to Lemma \ref{bounded_moment}, we have $\mathbb{E}[\Pi_{\Delta,T}^{-3}] \leq C_{v,d,3}$. For the other term, $\mathbb{E}[\Pi_{\Delta,T} S_{T}]$, we can handle the term as follows.
\begin{align*}
 \mathbb{E}[\Pi_{\Delta,T} S_{T}]&\le S_{0}+\mathbb{E}\Bigg[\Pi_{\Delta,T}\sum_{t=1}^{T}\|g_{t}\|^{2}\Bigg] \le dv+ \mathbb{E}\Bigg[\sum_{t=1}^{T}\Pi_{\Delta,T}\|g_{t}\|^{2}\Bigg]  \\&=dv+ \sum_{t=1}^{T}\mathbb{E}\big[\Pi_{\Delta,T}\mathbb{E}[\|g_{t}\|^{2}|\mathscr{F}_{t-1}]\big]\\& \mathop{\le}^{\text{Property \ref{property_-1}}}dv+ \sum_{t=1}^{T}\mathbb{E}\big[\Pi_{\Delta,T}((A+2L_{f}B)(f(w_{t})-f^{*})+C)\big]\\&\mathop{\le}^{\text{Lemma \ref{lem_g}}}dv+((A+2L_{f}B)M_{\delta}+C)T.
\end{align*}
This implies 
\begin{align*}
\mathbb{E}[\sqrt{S_{T}}]\le {C^{1/4}_{v,d,3}}(dv+((A+2L_{f}B)M_{\delta}+C)T^{3/4}=\mathcal{O}({T^{3/4}}).
\end{align*}
For the case where $\delta = 0$, we use the same approach as in the case of $\delta > 0$ and apply the corresponding conclusion for $\delta = 0$ from Lemma \ref{lem_g}. Thus, we obtain
\[\mathbb{E}[{S^{3/4}_{T}}]=\mathcal{O}({T^{3/4}}\ln^{3/2} T). \tag*{\qedhere}\]

According to the result from Lemma \ref{lem_sum}, it is straightforward to see that when $\delta > 0$,
\begin{align*}
  \sum_{t=2}^{T}\mathbb{E}\bigg[\Pi_{\Delta,t}\frac{\eta_{t-1}\|\nabla f(w_{t})\|^{2}}{\sqrt{\Sigma_{v_{t-1}}+\mu}}\bigg]&\le \sum_{t=2}^{T}\mathbb{E}\bigg[\Pi_{\Delta,t}\frac{\eta_{t-1}}{\sqrt{\Sigma_{v_{t-1}}+\mu}}\sum_{i=1}^{d}(\nabla_{i}f(w_{t}))^{2}\bigg]\\&\le \sum_{t=1}^{T}\mathbb{E}\bigg[\Pi_{\Delta,t}\sum_{i=1}^{d}\zeta_{i}(t)\bigg]\\&<C_{4,\delta}<+\infty.
\end{align*}
Next, we apply the \emph{Lebesgue's Monotone Convergence theorem}
\[\sum_{t=2}^{+\infty}{\Pi_{\Delta,t}}\frac{\eta_{t-1}\|\nabla f(w_{t})\|^{2}}{\sqrt{\Sigma_{v_{t-1}}+\mu}}<+\infty\ \ \text{a.s.}\]
Then, by combining the almost surely boundedness of $\sup_{t\ge 1}\Pi^{-1}_{\Delta,t}$ and ${\sup_{t\ge 1}\Sigma_{v_{t}}}$ from Lemma \ref{bounded_moment} and Lemma \ref{lem_v_t}, it follows
\begin{align*}
\sum_{t=1}^{+\infty}\eta_{t}\|\nabla f(w_{t})\|^{2}&\le \|\nabla f(w_{1})\|^{2}+\sum_{t=2}^{+\infty}\eta_{t-1}\|\nabla f(w_{t})\|^{2}\\&<\|\nabla f(w_{1})\|^{2}+\Big(\sup_{t\ge 1}\Pi^{-3/2}_{\Delta,t+1}\Big)\cdot\Big(\sqrt{\sup_{t\ge 1}\Pi_{\Delta,t}\Sigma_{v_{t}}}+\mu\Big)\cdot\sum_{t=2}^{+\infty}\Pi_{\Delta,t}\frac{\eta_{t-1}\|\nabla f(w_{t})\|^{2}}{\sqrt{\Sigma_{v_{t-1}}}+\mu}\\&<+\infty\ \ \text{\text{a.s.}}
\end{align*}
According to the L-smoothness assumption (Assumption \ref{ass_2}), it is immediate that
\[
|\|\nabla f(w_{t})\| - \|\nabla f(u_{t})\| |\leq L_{f} \|w_{t} - u_{t}\| = \frac{L_{f} \beta_{1}}{1 - \beta_{1}} \|\eta_{v_{t-1}} \circ m_{t-1}\|,\]
that is,
\begin{align*}
 \|\nabla f(u_{t})\|^{2}&\le\left(\|\nabla f(w_{t})\|+\frac{L_{f} \beta_{1}}{1 - \beta_{1}} \|\eta_{v_{t-1}} \circ m_{t-1}\|\right)^{2}\\&\le 2\|\nabla f(w_{t})\|^{2}+\frac{2L_{f}^{2}\beta_{1}^{2}}{(1-\beta_{1})^{2}} \|\eta_{v_{t-1}} \circ m_{t-1}\|^{2}.
\end{align*}
This implies 
\begin{align*}
    \sum_{t=1}^{+\infty}\eta_{t}\|\nabla f(u_{t})\|^{2}&\le 2\sum_{t=1}^{+\infty}\eta_{t}\|\nabla f(w_{t})\|^{2}+\frac{2L_{f}^{2}\beta_{1}^{2}}{(1-\beta_{1})^{2}} \sum_{t=1}^{+\infty}\|\eta_{v_{t-1}} \circ m_{t-1}\|^{2}.
\end{align*}
According to Property \ref{property_2}, for any \(\delta > 0\), 
\begin{align*}
   \left(\frac{L_{f} \beta_{1}}{1 - \beta_{1}} \right)^{2}\sum_{t=1}^{T}\mathbb{E}\|\eta_{v_{t-1}}\circ m_{t-1}\|^{2}&\le \mathcal{O}\left(\sum_{t=1}^{T}\mathbb{E}\|\eta_{v_{t}}\circ g_{t}\|^{2}\right)+\mathcal{O}(1)\\&\mathop{\le}^{\text{Eq. \ref{Gamma}}}\mathcal{O}(1).
\end{align*}
Applying the \emph{Lebesgue's Monotone Convergence theorem}, we obtain
\begin{align}\label{m_t}
 \left(\frac{L_{f} \beta_{1}}{1 - \beta_{1}} \right)^{2}\sum_{t=1}^{T}\|\eta_{v_{t-1}}\circ m_{t-1}\|^{2} <+\infty\ \ \text{a.s.,}  
\end{align}
that is
\begin{align*}
    \sum_{t=1}^{+\infty}\eta_{t}\|\nabla f(u_{t})\|^{2}&\le 2\sum_{t=1}^{+\infty}\eta_{t}\|\nabla f(w_{t})\|^{2}+\frac{2L_{f}^{2}\beta_{1}^{2}}{(1-\beta_{1})^{2}} \sum_{t=1}^{+\infty}\|\eta_{v_{t-1}} \circ m_{t-1}\|^{2}<+\infty\ \ \text{a.s..} \tag*{\qedhere}
\end{align*}

According to Lemma \ref{lem_sum}, we have:
\begin{align*}
    \sum_{t=1}^{T}\mathbb{E}\bigg[\Pi_{\Delta,t}\sum_{i=1}^{d}\zeta_{i}(t)\bigg]\le\begin{cases} 
C_{4,\delta}, & \text{if } \delta\in(0,1/2) \\
C_{5}+C_{6}\mathbb{E}\left[\ln(S_{T})\right], & \text{if } \delta = 0\end{cases}.
\end{align*}
According to the monotonicity of $\eta_{v_{t},i}$ in Property \ref{property_0} and the monotonicity of $\Pi_{\Delta,t}$ itself, we obtain the following inequality.
\begin{align*}
    \sum_{t=1}^{T}\mathbb{E}\Bigg[\Pi_{\Delta,T}\frac{\|\nabla f(w_{t})\|^{2}}{T^{\frac{1}{2}+\delta}(\sqrt{v_{T}}+\mu)}\bigg]\le  \sum_{t=1}^{T}\mathbb{E}\bigg[\Pi_{\Delta,T}\sum_{i=1}^{d}\zeta_{i}(t)\bigg]\le\begin{cases} 
C_{4,\delta}, & \text{if } \delta\in(0,1/2) \\
C_{5}+C_{6}\mathbb{E}\left[\ln(S_{T})\right], & \text{if } \delta = 0\end{cases}.
\end{align*}
For the leftmost part of the above inequality, we apply the \emph{Cauchy-Schwarz inequality} and obtain
\begin{align*}
\mathbb{E}\big[\Pi_{\Delta,T}^{-1}T^{\frac{1}{2}+\delta}(\sqrt{v_{T}}+\mu)\big]\Bigg( \sum_{t=1}^{T}\mathbb{E}\Bigg[\Pi_{\Delta,T}\frac{\|\nabla f(w_{t})\|^{2}}{T^{\frac{1}{2}+\delta}(\sqrt{v_{T}}+\mu)}\bigg]\Bigg) \ge \mathbb{E}\left[\sqrt{\sum_{t=1}^{T}\|\nabla f(w_{t})\|^{2}}\right],
\end{align*}
which means
\begin{align*}
\mathbb{E}\left[\sqrt{\sum_{t=1}^{T}\|\nabla f(w_{t})\|^{2}}\right] \le  \begin{cases} 
C_{4,\delta}\mathbb{E}\big[\Pi_{\Delta,T}^{-1}T^{\frac{1}{2}+\delta}(\sqrt{v_{T}}+\mu)\big], & \text{if } \delta\in(0,1/2) \\
C_{5}\mathbb{E}\big[\Pi_{\Delta,T}^{-1}T^{\frac{1}{2}+\delta}(\sqrt{v_{T}}+\mu)\big]+C_{6}\mathbb{E}\big[\Pi_{\Delta,T}^{-1}T^{\frac{1}{2}+\delta}(\sqrt{v_{T}}+\mu)\big]\mathbb{E}\left[\ln(S_{T})\right], & \text{if } \delta = 0\end{cases}.
\end{align*}
Combining the results from Lemma \ref{lem_S_T}, Lemma \ref{lem_v_t} and Lemma \ref{bounded_moment}, we obtain
\begin{align*}
   \mathbb{E}\big[\Pi_{\Delta,T}^{-1}T^{\frac{1}{2}+\delta}(\sqrt{v_{T}}+\mu)\big]&\le 2T^{\frac{1}{2}+\delta}\sqrt{\mathbb{E}[\Pi^{-3}_{\Delta,T}] }\sqrt{\mathbb{E}[\Pi_{\Delta,T}(v_{T}+\mu^{2})]}\\&\le \begin{cases} 
C^{1/2}_{v,d,3}\mathcal{O}(T^{\frac{1}{2}+\delta}), & \text{if } \gamma>1 \\
C^{1/2}_{v,d,3}\mathcal{O}({T}^{\frac{1}{2}+\delta}), & \text{if } \gamma=1,\ \delta \in(0,1]\\ C^{1/2}_{v,d,3}\mathcal{O}(\sqrt{T}\ln T), & \text{if } \gamma=1,\ \delta=0.\end{cases}
\end{align*} and
\begin{align*}
    \mathbb{E}[\ln(S_{T})]=\frac{4}{3}\mathbb{E}[\ln(S^{3/4}_{T})]\le \frac{4}{3}\ln(\mathbb{E}[S^{3/4}_{T}])=\begin{cases} 
\mathcal{O}(\ln T), & \text{if } \delta\in(0,1/2) \\
\mathcal{O}(\ln T)+\mathcal{O}(\ln\ln T), & \text{if } \delta = 0\end{cases}.
\end{align*}
Combining the two estimates above, we finally obtain
\begin{align}\label{sqrt}
 \mathbb{E}\left[\sqrt{\sum_{t=1}^{T}\|\nabla f(w_{t})\|^{2}}\right]\le  \begin{cases} 
\mathcal{O}(T^{\frac{1}{2}+\delta}), & \text{if }\delta\in(0,1/2)  \\
\mathcal{O}(\sqrt{T}\ln T), & \text{if } \gamma>1,\ \ \delta = 0\\
\mathcal{O}(\sqrt{T}\ln^{2} T), & \text{if } \gamma=1,\ \ \delta = 0.\end{cases}  
\end{align}
This implies that for any \( s \in (0,1) \), the inequality \begin{align*}
 \frac{1}{T}\sum_{t=1}^{T}\|\nabla f(w_{t})\|^{2}\le  \begin{cases} 
\mathcal{O}\Big(\frac{1}{s^2}\frac{1}{T^{\frac{1}{2}-\delta}}\Big), & \text{if }\delta\in(0,1/2)  \\
\mathcal{O}\Big(\frac{1}{s^2}\frac{\ln T}{\sqrt{T}}\Big), & \text{if } \gamma>1,\ \ \delta = 0\\
\mathcal{O}\Big(\frac{1}{s^2}\frac{\ln^{2} T}{\sqrt{T}}\Big), & \text{if } \gamma=1,\ \ \delta = 0\end{cases} \tag*{\qedhere}
\end{align*}
holds with probability at least \( 1 - s \).

Since we have already proved the almost sure convergence in Theorem \ref{thm:almost_sure}, it is natural to attempt to prove $L_1$ convergence via the \emph{Lebesgue's Dominated Convergence} theorem. To achieve this, we need to find a function $h$ that is $\mathscr{F}_{\infty}$-measurable and satisfies $\mathbb{E}|h| < +\infty$, and such that for all $t \geq 1$, we have $\|\nabla f(w_{t})\| \leq |h|.$ Since for all $t,$ we naturally have $\|\nabla f(w_{t})\| \leq \sup_{k \geq 1} \|\nabla f(w_{k})\|,$ we only need to prove that $\mathbb{E}[\sup_{k \geq 1} \|\nabla f(w_{k})\|] < +\infty.$ We proceed to achieve this goal in the rest of the proof.

Recall the \emph{Approximate Descent Inequality} (Lemma \ref{sufficient:decrease}). We have
\begin{align}\label{adam_16.01}
\Pi_{\Delta,t}\hat{f}(u_{t+1})-\Pi_{\Delta,t-1}\hat{f}(u_{t})\le& -\frac{1}{2}\Pi_{\Delta,t}\sum_{i=1}^{d}\zeta_{i}(t)\notag+C_{2}\|{\eta_{v_{t-1}}}\circ m_{t-1}\|^{2}+\sum_{i=1}^{d}\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|\\&\ +(L_{f}+1)\sum_{i=1}^{d}\eta_{v_{t},i}^{2}g_{t,i}^{2}+\Pi_{\Delta,t}M_{t}.
\end{align}
For any $\lambda > 0$, define the stopping time $\tau_{\lambda}$ as the first time the sequence $\{\Pi_{\Delta,t} \hat{f}(u_{t})\}_{t \geq 1}$ exceeds $\lambda$, i.e.,
\[\tau_{\lambda} := \min\{t \geq 2 : \Pi_{\Delta,t} \hat{f}(u_{t}) > \lambda\}.\]
It can be rigorously verified that $\tau_{\lambda}$ is a stopping time with respect to the filtration $\{\mathscr{F}_{t}\}_{t \geq 1}$, and satisfies a special property $[\tau_{\lambda} = n] \in \mathscr{F}_{n-1}$ for all $n \geq 1$. This implies that the preceding time $\tau_{\lambda} - 1$ is also a stopping time.
Next, for any deterministic time $T \geq 3$, we define $\tau_{\lambda,T} := \tau_{\lambda} \wedge T$. We then sum the indices of Equation (\ref{adam_16.01}) from $1$ to $\tau_{\lambda,T} - 1$. Specifically, we have
\begin{align*}
\Pi_{\Delta,\tau_{\lambda,T}-1}\hat{f}(u_{\tau_{\lambda,T}})\le& \Pi_{\Delta,0}\hat{f}(u_{1})+C_{2}\sum_{t=1}^{\tau_{\lambda,T}-1}\|{\eta_{v_{t-1}}}\circ m_{t-1}\|^{2}+\sum_{t=1}^{\tau_{\lambda,T}-1}\sum_{i=1}^{d}\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|\\&\ +(L_{f}+1)\sum_{t=1}^{\tau_{\lambda,T}-1}\sum_{i=1}^{d}\eta_{v_{t},i}^{2}g_{t,i}^{2}+\sum_{t=1}^{\tau_{\lambda,T}-1}\Pi_{\Delta,t}M_{t}.
\end{align*}
Taking the expectation on both sides, we obtain
\begin{align*}
\mathbb{E}\Big[\Pi_{\Delta,\tau_{\lambda,T}-1}\hat{f}(u_{\tau_{\lambda,T}})\Big]\le & \mathbb{E}\Big[\Pi_{\Delta,0}\hat{f}(u_{1})\Big]+C_{2}\mathbb{E}\left[\sum_{t=1}^{\tau_{\lambda,T}-1}\|{\eta_{v_{t-1}}}\circ m_{t-1}\|^{2}\right]\\&\ +\mathbb{E}\left[\sum_{t=1}^{\tau_{\lambda,T}-1}\sum_{i=1}^{d}\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|\right]+(L_{f}+1)\mathbb{E}\left[\sum_{t=1}^{\tau_{\lambda,T}-1}\sum_{i=1}^{d}\eta_{v_{t},i}^{2}g_{t,i}^{2}\right]\\&\ +\mathbb{E}\left[\sum_{t=1}^{\tau_{\lambda,T}-1}\Pi_{\Delta,t}M_{t}\right].
\end{align*}
Since $\{\Pi_{\Delta,t}M_{t}, \mathscr{F}_{t}\}_{t \geq 1}$ is a martingale difference sequence and $\tau_{\lambda,T} \le  T<+\infty$, by \emph{Doob's Stopped} theorem, we know that
\[\mathbb{E}\left[\sum_{t=1}^{\tau_{\lambda,T}-1}\Pi_{\Delta,t}M_{t}\right]=0.\]
This implies
\begin{align*}
\mathbb{E}\Big[\Pi_{\Delta,\tau_{\lambda,T}-1}\hat{f}(u_{\tau_{\lambda,T}})\Big]&\le \mathbb{E}\Big[\Pi_{\Delta,0}\hat{f}(u_{1})\Big]+C_{2}\mathbb{E}\left[\sum_{t=1}^{\tau_{\lambda,T}-1}\|{\eta_{v_{t-1}}}\circ m_{t-1}\|^{2}\right]\\&+\mathbb{E}\left[\sum_{t=1}^{\tau_{\lambda,T}-1}\sum_{i=1}^{d}\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|\right]+(L_{f}+1)\mathbb{E}\left[\sum_{t=1}^{\tau_{\lambda,T}-1}\sum_{i=1}^{d}\eta_{v_{t},i}^{2}g_{t,i}^{2}\right].
\end{align*}
Using Property \ref{property_2} and Lemma \ref{lem_sum'}, we obtain
\begin{align*}
