&\mathbb{E}[F_{T+1}]-\mathbb{E}[F_1]\notag\\\mathop{\le}^{\text{Lemma \ref{exchange}}}&\frac{1}{1-\sqrt{\beta_{1}}}(f(w_1)-f^*)-\frac{3(1-\beta_{1})}{8}\sum_{t=1}^{T}\sum_{i=1}^{d}\mathbb{E}\left[\eta_{v_{t-1},i}\Pi_{\Delta,t}(\nabla_{i}f(w_{t}))^{2}\right]\notag\\&+\frac{1}{1-\sqrt{\beta_{1}}}\left(\frac{D_{2}+F_1}{\sqrt{\beta_{1}}(1-\sqrt{\beta_{1}})}+\frac{L_{f}}{2}\right)\sum_{t=1}^{T}\mathbb{E}\left[\|\eta_{v_{t}}\circ m_{t}\|^{2}\right]+\frac{D_3}{\sqrt{v}(1-\sqrt{\beta_{1}})^{2}}.  
\end{align}
Using Lemma \ref{property_3.5}, we can transform the third term on the right side of the above inequality as follows
\begin{align*}
 \sum_{t=1}^{T}\mathbb{E}\left[\|\eta_{v_{t}}\circ m_{t}\|^{2}\right]&\le  (1-\beta_{1}) \sum_{t=1}^{T} \sum_{k=1}^{t}\beta_{1}^{t-k}\mathbb{E}\|\eta_{v_{t}}\circ g_{k}\|^{2}\mathop{\le}^{\text{Lemma \ref{exchange}}}  \sum_{t=1}^{T}\mathbb{E}\|\eta_{v_{t}}\circ g_{t}\|^{2}.
\end{align*}
Substituting this back into Equation (\ref{adam_w_2}) and rearranging the terms, we obtain the following two inequalities.
\begin{align}\label{adam_w_2'}
&\mathbb{E}[\Pi_{\Delta,t}(f(w_{t})-f^*)]\le \mathbb{E}[F_1]+\frac{1}{1-\sqrt{\beta_{1}}}(f(w_1)-f^*)+\frac{D_3}{\sqrt{v}(1-\sqrt{\beta_{1}})^{2}}\notag\\&+\frac{1}{1-\sqrt{\beta_{1}}}\left(\frac{D_{2}+F_1}{\sqrt{\beta_{1}}(1-\sqrt{\beta_{1}})}+\frac{L_{f}}{2}\right)\sum_{t=1}^{T}\mathbb{E}\|\eta_{v_{t}}\circ g_{t}\|^{2},  
\end{align}
and
\begin{align}\label{adam_w_2''}
&\sum_{t=1}^{T}\sum_{i=1}^{d}\mathbb{E}\left[\eta_{v_{t-1},i}\Pi_{\Delta,t}(\nabla_{i}f(w_{t}))^{2}\right]\le \frac{8}{3(1-\beta_{1})}\mathbb{E}[F_1]+\frac{8}{3(1-\beta_{1})}\frac{1}{1-\sqrt{\beta_{1}}}(f(w_1)-f^*)\notag\\&+\frac{D_3}{\sqrt{v}(1-\sqrt{\beta_{1}})^{2}}+\frac{8}{(1-\sqrt{\beta_{1}})3(1-\beta_{1})}\left(\frac{D_{2}+F_1}{\sqrt{\beta_{1}}(1-\sqrt{\beta_{1}})}+\frac{L_{f}}{2}\right)\sum_{t=1}^{T}\mathbb{E}\|\eta_{v_{t}}\circ g_{t}\|^{2}. 
\end{align}
Next, we proceed to estimate 
\[\sum_{t=1}^{T}\sum_{i=1}^{d}\mathbb{E}\left[\Pi_{\Delta,t}\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|\right]. \] 
We have
\begin{align*}
&\sum_{t=1}^{T}\sum_{i=1}^{d}\mathbb{E}\left[\Pi_{\Delta,t}\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|\right]\\\mathop{\le}^{\text{\emph{Cauchy-Schwarz} inequality }}&  \sum_{i=1}^{d}\sum_{t=1}^{T}\sqrt{\mathbb{E}\left[\Delta^{2}_{t,i}\Pi_{\Delta,t}(\nabla_{i} f(u_{t}))^{2}\right]}\cdot\sqrt{\mathbb{E}\left[\Pi_{\Delta,t}{m_{t-1,i}}  \right] }\\\le& \frac{1}{\sqrt{v}}\sum_{i=1}^{d}\sum_{t=1}^{T}\sqrt{\mathbb{E}\left[\eta_{v_{t-1},i}\Pi_{\Delta,t}(\nabla_{i} f(u_{t}))^{2}\right]}\cdot\sqrt{\mathbb{E}\left[\Pi_{\Delta,t}{m^{2}_{t-1,i}}  \right] }\\\mathop{\le}^{\text{\emph{Cauchy-Schwarz} inequality }}&  \frac{1}{\sqrt{v}}\sum_{i=1}^{d}\sqrt{\sum_{t=1}^{T}\mathbb{E}\left[\eta_{v_{t-1},i}\Pi_{\Delta,t}(\nabla_{i} f(u_{t}))^{2}\right]}\cdot\sqrt{\sum_{t=1}^{T}\mathbb{E}\left[\Pi_{\Delta,t}m^{2}_{t-1,i}\right]}\\\mathop{\le}^{\text{\emph{Cauchy-Schwarz} inequality }}&  \frac{1}{\sqrt{v}}\sqrt{\sum_{i=1}^{d}\sum_{t=1}^{T}\mathbb{E}\left[\eta_{v_{t-1},i}\Pi_{\Delta,t}(\nabla_{i} f(u_{t}))^{2}\right]}\cdot\sqrt{\sum_{t=1}^{T}\mathbb{E}\left[\Pi_{\Delta,t}\|m_{t-1}\|^2\right]}  \\\mathop{\le}^{\text{Lemma \ref{property_3.5}}}&\frac{\sqrt{1-\beta_{1}}}{\sqrt{v}}\sum_{i=1}^{d}\sqrt{\sum_{t=1}^{T}\mathbb{E}\left[\eta_{v_{t-1},i}\Pi_{\Delta,t}(\nabla_{i} f(u_{t}))^{2}\right]}\cdot\sqrt{\sum_{t=1}^{T}\sum_{k=1}^{t}\beta_{1}^{t-k}\mathbb{E}[\Pi_{\Delta,t}\|g_{k}\|^{2}]}\\\mathop{\le}^{(a)}&\mathcal{O}\left(\sum_{t=1}^{T}\mathbb{E}[\|\eta_{v_{t}}\circ g_{t}\|^{2}]\right)+\mathcal{O}(1).
\end{align*}
In the final step \((a)\), we first apply Property \ref{property_-1} to bound \(\mathbb{E}[\Pi_{\Delta,t}\|g_{t}\|^{2}]\) for all \( t \leq T \), by \(\mathbb{E}[\Pi_{\Delta,t}(f(w_{t}) - f^*)]\) for \( t \leq T \). Then, using Equation (\ref{adam_w_2'}), we further bound \(\mathbb{E}[\Pi_{\Delta,t}(f(w_{t}) - f^*)]\) as \(\mathcal{O}\left(\sum_{t=1}^{T} \|\eta_{v_{t}} \circ g_{t}\|^{2}\right)\). Finally, we apply Equation (\ref{adam_w_2''}) to the previous summation. This completes the proof.

\begin{align*}
&\sum_{t=1}^{n} (\sqrt{\beta_{1}})^{n-t} \left(\Pi_{\Delta,t+1}(f(w_{t+1}) - f^*) - \Pi_{\Delta,t}(f(w_{t}) - f^*)\right)\\&=\sum_{t=1}^{n} (\sqrt{\beta_{1}})^{n-t}\Pi_{\Delta,t+1}(f(w_{t+1}) - f^*)-\sum_{t=1}^{n} (\sqrt{\beta_{1}})^{n-t}\Pi_{\Delta,t}(f(w_{t}) - f^*)\\&=\sum_{t=1}^{n} (\sqrt{\beta_{1}})^{(n+1)-(t+1)}\Pi_{\Delta,t+1}(f(w_{t+1}) - f^*)-\sum_{t=1}^{n} (\sqrt{\beta_{1}})^{n-t}\Pi_{\Delta,t}(f(w_{t}) - f^*)\\&=\sum_{t=2}^{n+1} (\sqrt{\beta_{1}})^{(n+1)-t}\Pi_{\Delta,t}(f(w_{t}) - f^*)-\sum_{t=1}^{n} (\sqrt{\beta_{1}})^{n-t}\Pi_{\Delta,t}(f(w_{t}) - f^*)\\&=-(\sqrt{\beta_{1}})^{n}(f(w_1)-f^*)\\&\quad+\underbrace{\sum_{t=1}^{n+1} (\sqrt{\beta_{1}})^{(n+1)-t}\Pi_{\Delta,t}(f(w_{t}) - f^*)}_{F_{n+1}}-\underbrace{\sum_{t=1}^{n} (\sqrt{\beta_{1}})^{n-t}\Pi_{\Delta,t}(f(w_{t}) - f^*)}_{F'_{n}}.
\end{align*}
